r\n続報もお楽しみにお待ちください。<br>\r\n<iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/hNqe85-q5bQ\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen></iframe>'),(51649,6181,'_comment','field_6450bfdc8eea5'),(51650,6181,'price','22,000'),(51651,6181,'_price','field_63c249f43a52b'),(51652,6181,'listpice',''),(51653,6181,'_listpice','field_63c249f43a560'),(51654,6181,'year',''),(51655,6181,'_year','field_63c249f43a602'),(51656,6181,'condition','新品'),(51657,6181,'_condition','field_63c249f43a638'),(51658,6181,'stock','out'),(51659,6181,'_stock','field_63c249f43a6a3'),(51660,6181,'button','store'),(51661,6181,'_button','field_6450b13b42fe3'),(51662,6181,'store-url','https://funkojisan.shop/items/646f72126e3db50031ce98ab'),(51663,6181,'_store-url','field_646737b1721ae'),(51664,6181,'video_field',''),(51665,6181,'_video_field','field_6464756246359'),(51666,6181,'video_field2',''),(51667,6181,'_video_field2','field_646af7377615e'),(51668,6181,'video_field3',''),(51669,6181,'_video_field3','field_646af7437615f'),(51672,6185,'_wp_attached_file','2023/11/IMG20231108185453-scaled.jpg'),(51673,6185,'_wp_attachment_metadata','a:7:{s:5:\"width\";i:1920;s:6:\"height\";i:2560;s:4:\"file\";s:36:\"2023/11/IMG20231108185453-scaled.jpg\";s:8:\"filesize\";i:443017;s:5:\"sizes\";a:6:{s:6:\"medium\";a:5:{s:4:\"file\";s:29:\"IMG20231108185453-225x300.jpg\";s:5:\"width\";i:225;s:6:\"height\";i:300;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:16223;}s:5:\"large\";a:5:{s:4:\"file\";s:30:\"IMG20231108185453-768x1024.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:1024;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:104779;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:29:\"IMG20231108185453-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:7490;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:3